import {emptyState,dateKey,dateObj,addDays,weekStart,nextWeek,range,dayType,freshDay,totals,average,parsePlan,validateBackup,validateMeal,report,reviewPrompt,planPrompt,validDate,sessionsFor,validateTraining,normalizeIntensity} from './core.js?v=1.4.3';
import {parseMeals,applyMeals,copyDates,photoPrompt,captureTime} from './meal-tools.js?v=1.4.3';
import {groceryList,groceryText} from './grocery-tools.js?v=1.4.3';
import {attachMealSwipes} from './swipe-tools.js?v=1.4.3';
import {saveWorkout} from './workout-tools.js?v=1.4.3';
const KEY='fuel-and-flow-v1';let state=emptyState(),storageOK=true;
try{const saved=localStorage.getItem(KEY);if(saved)state=validateBackup(JSON.parse(saved));}catch(e){storageOK=false;}
let view='today',selected=dateKey(),period='week',planStart=nextWeek(),planDay=planStart,draft=null,coachPrompt='',coachMode='review',installEvent=null;
const $=s=>document.querySelector(s);const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>',food:'<path d="M5 3v6a3 3 0 0 0 6 0V3M8 3v19M19 3v19m0-19c-4 3-4 9 0 10"/>',chart:'<path d="M4 3v17h17M8 15l4-6 4 3 5-7"/>',chat:'<path d="M21 11a9 9 0 0 1-9 9H5l-3 2 1-6a9 9 0 1 1 18-5Z"/><path d="M7 9h10M7 13h7"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="m10 2-1 3-3 1-3-1-2 4 2 2v3l-2 2 2 4 3-1 3 1 1 3h4l1-3 3-1 3 1 2-4-2-2v-3l2-2-2-4-3 1-3-1-1-3Z"/>',plus:'<path d="M12 5v14M5 12h14"/>',drop:'<path d="M12 2s-7 8-7 13a7 7 0 0 0 14 0c0-5-7-13-7-13Z"/>',bolt:'<path d="m13 2-9 12h7l-1 8 10-12h-7Z"/>',copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',check:'<path d="m5 12 4 4L20 5"/>',trash:'<path d="M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7m4-7v7"/>',edit:'<path d="m4 16-1 5 5-1L21 7l-4-4Z M14 6l4 4"/>',weight:'<path d="M5 4h14l2 17H3Z"/><path d="M8 7a5 5 0 0 1 8 0m-4 1 2-2"/>',moon:'<path d="M20 15A9 9 0 0 1 9 3a9 9 0 1 0 11 12Z"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.sun}</svg>`;
const fmt=(v,unit='')=>v===null||v===undefined||v===''?'—':`${Number(v).toLocaleString(undefined,{maximumFractionDigits:1})}${unit}`;
const pretty=k=>dateObj(k).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'});
const time=t=>{const [h,m]=t.split(':');return `${(+h%12)||12}:${m} ${+h>=12?'PM':'AM'}`;};
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3500);}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;return true;}catch(e){storageOK=false;toast('Could not save on this device. Export a backup before closing.');return false;}}
function d(){return state.days[selected]||freshDay(selected,state.weeklyTraining);}
function ensure(){return state.days[selected]??=freshDay(selected,state.weeklyTraining);}
function target(day=d()){const carb=day.type.includes('BJJ')?state.profile.bjjCarbs:state.profile.otherCarbs;return {protein:state.profile.protein===''?null:Number(state.profile.protein),carbs:carb===''?null:Number(carb),fat:state.profile.fat===''?null:Number(state.profile.fat)};}
function stat(label,value,sub,i,color='',fraction=null){return `<div class="card stat"><div class="stat-top">${label}<span class="stat-icon ${color}">${icon(i)}</span></div><div class="stat-value">${value}</div><div class="small muted">${sub}</div>${fraction!==null?`<div class="track"><i style="width:${Math.min(100,Math.max(0,fraction*100))}%"></i></div>`:''}</div>`;}
function swipeHint(){return `<button type="button" class="swipe-hint" data-swipe-toggle aria-label="Show or hide row actions">${icon('arrow')} <span>Swipe right for options</span></button>`;}
function swipeRecord(body,actions,label){const width=actions.length*72;return `<div class="swipe-meal" data-swipe-width="${width}" style="--swipe-width:${width}px"><div class="meal-swipe-actions" aria-hidden="true">${actions.map(a=>`<button type="button" class="swipe-action swipe-${a.kind}" tabindex="-1" ${a.attrs} aria-label="${a.label} ${esc(label)}">${icon(a.icon)}<span>${a.label}</span></button>`).join('')}</div><div class="meal meal-front" tabindex="0" role="group" aria-label="${esc(label)}. Swipe right for row actions." aria-expanded="false"><div class="meal-body">${body}${swipeHint()}</div></div></div>`;}
function mealsHTML(meals,planned=false,date=selected,interactive=true){return meals.length?meals.map((m,i)=>{const actionData=planned?`data-date="${date}" data-index="${i}"`:`data-id="${esc(m.id)}"`;const edit=planned?'edit-planned-meal':'edit-meal',remove=planned?'delete-planned-meal':'delete-meal';const front=`<div class="meal${interactive?' meal-front':''}" ${interactive?`tabindex="0" role="group" aria-label="${esc(m.name)}. Swipe right or press Right Arrow for Edit and Delete." aria-expanded="false"`:''}><div class="meal-time">${esc(time(m.time))}</div><div class="meal-body"><h3>${esc(m.name)}</h3><p>${esc(m.portion)}</p><div class="nutrition">${fmt(m.calories)} kcal · P ${fmt(m.protein)}g · C ${fmt(m.carbs)}g · F ${fmt(m.fat)}g</div>${interactive?swipeHint():''}</div>${planned&&interactive?`<div class="meal-buttons"><button class="btn soft" data-action="eat-plan" data-date="${date}" data-index="${i}">${icon('check')} Log eaten</button></div>`:''}</div>`;return interactive?`<div class="swipe-meal"><div class="meal-swipe-actions" aria-hidden="true"><button class="swipe-action swipe-edit" tabindex="-1" data-action="${edit}" ${actionData} aria-label="Edit ${esc(m.name)}">${icon('edit')}<span>Edit</span></button><button class="swipe-action swipe-delete" tabindex="-1" data-action="${remove}" ${actionData} aria-label="Delete ${esc(m.name)}">${icon('trash')}<span>Delete</span></button></div>${front}</div>`:front;}).join(''):`<div class="empty">${icon('food')}<p>${planned?'No plan for this day yet.':'Your food log starts here.'}</p><span class="small">${planned?'Import a week from ChatGPT or add your own meals.':'Add a meal, use a favorite, or log a planned meal as eaten.'}</span></div>`;}
function macroHTML(t,g){return `<div class="macro-row">${['protein','carbs','fat'].map((k,i)=>`<div class="macro"><span class="small muted">${['Protein','Carbs','Fat'][i]}</span><strong>${fmt(t[k])}<span class="small muted"> / ${fmt(g[k])}g</span></strong><div class="track"><i style="width:${Math.min(100,g[k]?t[k]/g[k]*100:0)}%"></i></div></div>`).join('')}</div>`;}
function energyCard(day){return `<section class="card stat energy-card" aria-label="Energy Levels before and after training"><div class="stat-top">Energy Levels<span class="stat-icon coral">${icon('bolt')}</span></div><div class="energy-metrics">${[['Before training',day.energyBefore],['After training',day.energyAfter]].map(([label,value])=>`<div class="energy-metric"><span class="energy-caption">${label}</span><div class="energy-value">${fmt(value)} <span>/10</span></div><div class="track"><i style="width:${value==null?0:Math.min(100,Math.max(0,Number(value)*10))}%"></i></div></div>`).join('')}</div><div class="small muted">${state.profile.energyGoal!==''?`Target: ${esc(state.profile.energyGoal)}/10`:'Log both in your daily check-in'}</div></section>`;}
function todayHTML(){const day=d(),t=totals(day.meals),g=target(day),bjj=day.type.includes('BJJ'),week=range(selected,'week'),w=average(week.map(k=>state.days[k]?.weight));return `<div class="hero card"><div><div class="eyebrow">Fuel well. Move well.</div><h2>${bjj?'Build energy before you hit the mat.':'A little consistency goes a long way.'}</h2><p>${bjj?`Prioritize fuel and check in before your ${bjjLabel(selected)} class.`:'Track what you eat, how you feel, and how you recover.'}</p></div><div class="hero-side"><span class="small">PRE-BJJ ENERGY GOAL</span><strong>${fmt(state.profile.energyGoal)}<span class="small"> / 10</span></strong><span class="small">${state.profile.energyBaseline!==''?`Your starting point: ${esc(state.profile.energyBaseline)}/10`:'Set your energy target in Settings'}</span></div></div>${!storageOK?'<div class="banner">Device storage is unavailable or the saved data could not be read. Export a backup of any new entries before closing. Your existing stored data has not been overwritten.</div>':''}<div class="stats">${stat('Calories logged',`${fmt(t.calories)} <span>kcal</span>`,state.profile.calories?`Reference: ${fmt(state.profile.calories)} kcal · ${day.complete?'complete':'partial'} log`:day.complete?'Food log marked complete':'Partial until you mark complete','food','',state.profile.calories?t.calories/Number(state.profile.calories):null)}${energyCard(day)}${stat('Hydration',`${fmt(day.water)} <span>${Number(state.profile.hydrationGoal)>0?'/ '+fmt(state.profile.hydrationGoal)+' ':''}oz</span>`,Number(state.profile.hydrationGoal)>0?(day.water==null?'Daily goal · fluids not logged':`${Math.round(day.water/Number(state.profile.hydrationGoal)*100)}% of daily goal${day.water>=Number(state.profile.hydrationGoal)?' · Goal reached':''}`):'Set a hydration goal in Settings','drop','blue',Number(state.profile.hydrationGoal)>0?(day.water??0)/Number(state.profile.hydrationGoal):null)}${stat('Week’s average weight',`${fmt(w)} <span>lb</span>`,'Logged weights · missing days excluded','weight','violet')}</div><div class="columns"><div class="stack"><section class="card"><div class="card-head"><div><h2>Food for today</h2><span class="small muted">Logged meals · swipe right to edit or delete</span></div><button class="btn" data-action="add-meal">${icon('plus')} Add food</button></div>${macroHTML(t,g)}<div class="actions" style="margin-bottom:16px"><button class="btn secondary" data-action="favorites">${icon('food')} Your usual foods</button><button class="btn secondary" data-action="meal-import">Import meal / photo</button><button class="btn secondary" data-action="show-today-plan">View planned meals</button></div>${mealsHTML(day.meals)}<hr class="divider"><label class="check"><input type="checkbox" id="complete" ${day.complete?'checked':''}> I have logged all food and drinks for this day</label><p class="small muted">Partial logs are excluded from complete-day calorie averages.</p></section><section class="card"><div class="card-head"><button class="btn secondary" data-action="training-schedule">Edit schedule</button><h2>Today’s training</h2><span class="pill">${esc(day.type)}</span></div><div class="fields"><label class="field">Training type<select id="training-type">${['Rest','Weights','BJJ','BJJ + weights','Other'].map(x=>`<option ${x===day.type?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">Scheduled focus<input value="${esc(sessionsFor(selected,state.weeklyTraining).map(x=>x.title).join(' · ')||'No sessions / rest')}" disabled></label></div><div class="hint">Use your recurring schedule as a plan and record the training you actually do. Make time for recovery.</div></section></div><div class="stack"><section class="card"><div class="card-head"><div><h2>Your daily check-in</h2><span class="small muted">No entry is treated as unknown</span></div><span class="pill coral">Feel → fuel → recover</span></div><form id="checkin"><div class="fields"><label class="field">Before training energy /10<input name="energyBefore" type="number" min="1" max="10" step="1" placeholder="1–10" value="${day.energyBefore??''}"></label><label class="field">After training energy /10<input name="energyAfter" type="number" min="1" max="10" step="1" placeholder="1–10" value="${day.energyAfter??''}"></label><label class="field">Sleep last night (hours)<input name="sleep" type="number" min="0" max="24" step="0.1" value="${day.sleep??''}" placeholder="e.g. 7.5"></label><label class="field">Fluids total (oz)<input name="water" type="number" min="0" max="500" step="1" value="${day.water??''}" placeholder="Water + other drinks"></label><label class="field">Morning weight (lb)<input name="weight" type="number" min="1" max="1000" step="0.1" value="${day.weight??''}" placeholder="Same conditions each day"></label><label class="field">Waist (in, optional)<input name="waist" type="number" min="1" max="200" step="0.1" value="${day.waist??''}"></label><label class="field">BJJ minutes<input name="bjjMinutes" type="number" min="0" max="500" value="${day.bjjMinutes??''}"></label><label class="field">Lifting minutes<input name="liftMinutes" type="number" min="0" max="500" value="${day.liftMinutes??''}"></label><label class="field wide">Recovery<select name="recovery"><option value="">Not logged</option>${['Poor','Okay','Good'].map(x=>`<option ${day.recovery===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field wide">Notes<textarea name="notes" maxlength="3000" placeholder="Hunger, soreness, stress, class performance…">${esc(day.notes)}</textarea></label></div><button class="btn" style="width:100%;margin-top:17px">${icon('check')} Save check-in</button></form></section>${bjj?`<section class="card"><h2>Your afternoon fuel guide</h2><div class="timeline"><div class="timeline-row"><span class="dot"></span><strong>${esc(fuelLabel(-180))}</strong><span>Carbs + protein<br><span class="muted small">40–60g carbs · 15–25g protein</span></span></div><div class="timeline-row"><span class="dot"></span><strong>${esc(fuelLabel(-45))}</strong><span>Optional quick fuel<br><span class="muted small">20–30g easy-to-digest carbs</span></span></div><div class="timeline-row"><span class="dot"></span><strong>${esc(bjjLabel(selected))}</strong><span>BJJ · water and electrolytes</span></div><div class="timeline-row"><span class="dot"></span><strong>After</strong><span>Chicken, rice + vegetables</span></div></div><span class="small muted">Flexible timing guide from your current trial.</span></section>`:''}</div></div>`;}
function groceryHTML(){const list=groceryList(state,planStart),checked=state.groceryChecks[planStart]||[];return `<section class="card grocery-card" style="margin-top:22px"><div class="card-head"><div><h2>Grocery list</h2><span class="small muted">${pretty(planStart)} – ${pretty(addDays(planStart,6))} · ${list.mealCount} planned meals</span></div><button class="btn secondary" data-action="copy-groceries" ${!list.items.length?'disabled':''}>${icon('copy')} Copy list</button></div><p class="small muted">Foods from your planned portion descriptions. Matching foods and units are combined; review unclear descriptions before shopping.</p>${list.items.length?`<div class="grocery-grid">${list.items.map((item,i)=>`<div class="grocery-item ${checked.includes(item.key)?'grocery-done':''}"><label class="check"><input type="checkbox" data-grocery-index="${i}" ${checked.includes(item.key)?'checked':''}><span><strong>${esc(item.name)}</strong><span class="small muted grocery-amount">${item.amount===null?'Amount not specified':fmt(item.amount)+(item.unit?' '+esc(item.unit):'')+' planned'} · ${item.uses} use${item.uses===1?'':'s'}</span></span></label><details class="small muted"><summary>View planned portions</summary><p>${item.descriptions.map(esc).join(' / ')}</p><p>${item.sources.map(x=>`${esc(pretty(x.date))}: ${esc(x.meal)}`).join('<br>')}</p></details></div>`).join('')}</div><p class="small muted">${list.items.filter(x=>checked.includes(x.key)).length} of ${list.items.length} items checked</p>`:'<div class="empty">Add meals to this week’s plan to build your grocery list.</div>'}</section>`;}
function planHTML(){const days=range(planStart,'week'),p=state.plans[planDay],t=totals(p?.meals||[]);return `<div class="hero card"><div><div class="eyebrow">Make the week easier</div><h2>A plan that fits your training.</h2><p>Plan with ChatGPT, review the meals, then log what you actually eat.</p></div><button class="btn soft" data-action="plan-coach">${icon('chat')} Plan with ChatGPT</button></div><div class="plan-toolbar" style="margin-top:23px"><div class="actions"><button class="btn secondary" data-action="plan-prev" aria-label="Previous week">←</button><h2 style="margin:0">${pretty(planStart)} – ${pretty(addDays(planStart,6))}</h2><button class="btn secondary" data-action="plan-next" aria-label="Next week">→</button></div><button class="btn secondary" data-action="next-week">Upcoming week</button></div><div class="week-strip">${days.map(k=>`<button class="daybtn ${k===planDay?'active':''}" data-action="plan-day" data-date="${k}"><span class="small">${dateObj(k).toLocaleDateString(undefined,{weekday:'short'})}</span><strong>${dateObj(k).getDate()}</strong><span class="mini">${dayType(k,state.weeklyTraining).includes('BJJ')?'BJJ':dayType(k,state.weeklyTraining).toUpperCase()}</span><div class="mini" style="margin-top:5px">${state.plans[k]?.meals.length||0} meals</div></button>`).join('')}</div><div class="columns"><section class="card"><div class="card-head"><div><h2>${pretty(planDay)}</h2><span class="small muted">Planned · ${dayType(planDay,state.weeklyTraining)} · swipe right to edit or delete</span></div><button class="btn" data-action="add-plan">${icon('plus')} Add meal</button></div><div class="inline-metrics"><div><strong>${fmt(t.calories)}</strong><span>planned kcal</span></div><div><strong>${fmt(t.protein)}g</strong><span>protein</span></div><div><strong>${fmt(t.carbs)}g</strong><span>carbs</span></div><div><strong>${fmt(t.fat)}g</strong><span>fat</span></div></div>${mealsHTML(p?.meals||[],true,planDay)}${p?.notes?`<div class="hint">${esc(p.notes)}</div>`:''}${p?.meals.length?`<button class="btn secondary" style="margin-top:15px" data-action="edit-plan-day">${icon('edit')} Edit or remove planned meals</button>`:''}</section><div class="stack"><section class="card"><div class="card-head"><h2>Your weekly rhythm</h2><button class="btn secondary" data-action="training-schedule">Edit schedule</button></div>${range(planStart,'week').map(k=>`<div class="schedule-row"><b>${dateObj(k).toLocaleDateString(undefined,{weekday:'short'})}</b><span>${esc(sessionsFor(k,state.weeklyTraining).map(x=>x.title+(x.time?' · '+time(x.time):'')).join(' / ')||'No sessions / rest')}</span></div>`).join('')}<div class="hint">Edit each day’s actual training in Today. Tell ChatGPT about schedule changes when generating a plan.</div></section><section class="card"><h2>Plan → eat → track</h2><p class="small muted">“Log eaten” adds one serving to that day’s food log. You can edit the portions and estimated nutrition afterward. Repeat servings are allowed with confirmation.</p><p class="small muted">An imported plan never counts as food eaten and never changes your energy check-ins.</p></section></div></div>${groceryHTML()}`;}
function insightsHTML(){const r=report(state,selected,period),keys=range(selected,period),last7=Array.from({length:7},(_,i)=>addDays(selected,i-6)),weightNow=average(last7.map(k=>state.days[k]?.weight)),weightPrev=average(last7.map(k=>state.days[addDays(k,-7)]?.weight)),diff=weightNow!=null&&weightPrev!=null?Math.round((weightNow-weightPrev)*10)/10:null;return `<div class="plan-toolbar"><div><h2>Your patterns, at a glance.</h2><p class="muted small">Logged observations, not automatic diet prescriptions.</p></div><div class="tabs">${['day','week','month'].map(x=>`<button class="${period===x?'active':''}" data-action="period" data-period="${x}">${x[0].toUpperCase()+x.slice(1)}</button>`).join('')}</div></div><p class="small muted">${pretty(r.from)} – ${pretty(r.to)} · ${r.daysWithEntries} days with entries · ${r.completedFoodLogs} complete food logs</p><div class="stats">${stat('Average before training',`${fmt(r.averages.energyBefore)} <span>/10</span>`,'Only days with an energy entry','bolt','coral')}${stat('Average sleep',`${fmt(r.averages.sleepHours)} <span>hours</span>`,'Only nights you logged','moon','violet')}${stat('7-day average weight',`${fmt(weightNow)} <span>lb</span>`,diff===null?'Log weights across two weeks for a comparison':`${diff>0?'+':''}${diff} lb vs previous 7 days`,'weight')}${stat('Average complete-day food',`${fmt(r.averages.caloriesOnCompleteDays)} <span>kcal</span>`,`${r.completedFoodLogs} complete days · partial logs excluded`,'food','blue')}</div><div class="columns"><section class="card"><div class="card-head"><h2>Energy before training</h2><span class="pill">Last 7 days</span></div><p class="small muted">${state.profile.energyGoal!==''?`Goal: ${esc(state.profile.energyGoal)}/10 · `:''}Missing values show a dash</p><div class="chart">${last7.map(k=>{const e=state.days[k]?.energyBefore;return `<div class="bar-item"><div class="bar" style="height:${e?e*10:1}%;background:${e>=6?'var(--green)':'var(--coral)'}"><span>${e??'—'}</span></div><small>${dateObj(k).toLocaleDateString(undefined,{weekday:'short'})} ${dateObj(k).getDate()}</small></div>`;}).join('')}</div></section><section class="card"><h2>Read the trend with context</h2><p class="small muted">More carbohydrate, creatine and hard training can influence scale weight. Compare seven-day averages alongside waist, sleep and performance.</p><div class="hint">Missing meals, energy and sleep are unknown. Mark food logs complete before using their calorie totals to assess intake.</div><button class="btn" data-action="review-coach">${icon('chat')} Review ${period} with ChatGPT</button></section></div><section class="card" style="margin-top:22px"><div class="card-head"><h2>${period[0].toUpperCase()+period.slice(1)} log</h2><button class="btn secondary" data-action="copy-review">${icon('copy')} Copy review prompt</button></div><div class="table-scroll"><table><thead><tr><th>Date</th><th>Food log</th><th>Calories</th><th>P / C / F (g)</th><th>Energy pre / post</th><th>Sleep</th><th>Weight</th><th>Training</th></tr></thead><tbody>${keys.map(k=>{const x=state.days[k],t=totals(x?.meals);return `<tr><td><button class="iconbtn" data-action="open-day" data-date="${k}">${pretty(k)}</button></td><td>${!x?'No entry':x.complete?'Complete':'Partial'}</td><td>${x?.meals.length||x?.complete?fmt(t.calories):'—'}</td><td>${x?.meals.length?`${fmt(t.protein)} / ${fmt(t.carbs)} / ${fmt(t.fat)}`:'—'}</td><td>${fmt(x?.energyBefore)} / ${fmt(x?.energyAfter)}</td><td>${fmt(x?.sleep)}</td><td>${fmt(x?.weight)}</td><td>${esc(x?.type||dayType(k,state.weeklyTraining))}</td></tr>`;}).join('')}</tbody></table></div></section>`;}
function coachHTML(){return `<div class="actions" style="margin-bottom:18px"><button class="btn soft" data-action="meal-import">${icon('food')} Import meal / photo</button></div><div class="hero card"><div><div class="eyebrow">Your ChatGPT handoff</div><h2>Better conversations. Better plans.</h2><p>Copy your context out. Bring a structured meal plan back. You control every step.</p></div>${icon('chat')}</div><div class="columns" style="margin-top:22px"><section class="card"><div class="step"><span class="step-number">1</span><div><h2>Choose your prompt</h2><span class="small muted">Uses your profile and real logged data.</span></div></div><div class="tabs" style="margin-bottom:18px"><button data-action="coach-mode" data-mode="review" class="${coachMode==='review'?'active':''}">Review results</button><button data-action="coach-mode" data-mode="plan" class="${coachMode==='plan'?'active':''}">Plan next week</button></div>${coachMode==='review'?`<div class="fields"><label class="field">Review period<select id="review-period">${['day','week','month'].map(x=>`<option value="${x}" ${period===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">Date in period<input type="date" id="review-date" value="${selected}" required></label></div>`:`<label class="field">Monday starting the plan<input type="date" id="coach-week" value="${planStart}" required></label><div class="hint">Generate a fresh prompt after changing your profile or the week. ChatGPT must return the exact JSON format included in the prompt.</div>`}<button class="btn" style="margin:17px 0" data-action="generate">${icon('bolt')} Generate prompt</button><label class="field">Copy this into ChatGPT<textarea id="prompt-output" class="prompt-box" readonly placeholder="Your generated prompt will appear here…">${esc(coachPrompt)}</textarea></label><div class="actions" style="margin-top:15px"><button class="btn soft" data-action="copy-prompt" ${!coachPrompt?'disabled':''}>${icon('copy')} Copy prompt</button><a class="btn secondary" href="https://chatgpt.com/" target="_blank" rel="noopener">Open ChatGPT ↗</a></div><p class="small muted">No API key needed. Nothing is sent to ChatGPT until you copy and paste it.</p></section><section class="card"><div class="step"><span class="step-number">2</span><div><h2>Bring your meal plan back</h2><span class="small muted">Paste the complete JSON returned by ChatGPT.</span></div></div><label class="field">Import into the week beginning<input type="date" id="import-week" value="${planStart}" required></label><label class="field" style="margin-top:15px">ChatGPT response<textarea id="plan-input" class="prompt-box" placeholder='{"schemaVersion":1,"weekStart":"…","days":[…]}'></textarea></label><button class="btn" style="margin-top:15px" data-action="preview-import">${icon('check')} Validate & preview</button><div id="import-preview"></div><div class="hint">Review all seven days before importing. Import replaces planned meals for that week; food eaten and daily check-ins stay separate. Nutrition values remain estimates.</div></section></div>`;}
function settingsHTML(){const p=state.profile;const field=(key,label,type='text')=>`<label class="field">${label}<input name="${key}" type="${type}" value="${esc(p[key])}" ${type==='number'?'min="0" max="10000" step="0.1"':''}></label>`;return `<div class="columns"><section class="card"><div class="card-head"><h2>Your profile & reference targets</h2><span class="pill">v1.4.3</span></div><p class="small muted">Your profile and targets stay in this browser. Enter your own details; blank fields remain unknown.</p><form id="settings"><div class="fields" style="margin-top:20px">${field('name','Name')}${field('age','Age','number')}<label class="field">Sex<select name="sex"><option value="">Not set</option>${['Male','Female'].map(x=>`<option value="${x}" ${p.sex===x?'selected':''}>${x}</option>`).join('')}</select></label>${field('startWeight','Starting weight (lb)','number')}${field('height','Height (e.g. 5 ft 10 in)')}${field('weight','Latest reported weight (lb)','number')}${field('goalWeight','Goal weight (optional)','number')}${field('energyGoal','Energy goal /10','number')}${field('hydrationGoal','Hydration goal (oz/day)','number')}${field('energyBaseline','Starting energy /10 (optional)','number')}${field('protein','Daily protein reference (g)','number')}${field('bjjCarbs','BJJ-day carb reference (g)','number')}${field('otherCarbs','Other-day carb reference (g)','number')}${field('fat','Daily fat reference (g)','number')}${field('calories','Optional calorie target (kcal)','number')}<label class="field">Appearance<select name="theme">${['light','dark','system'].map(x=>`<option ${p.theme===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field wide">Food preferences & meal timing<textarea name="preferences" maxlength="3000">${esc(p.preferences)}</textarea></label><label class="field wide">Allergies, restrictions & other context<textarea name="restrictions" maxlength="3000" placeholder="Include dietary restrictions or schedule changes…">${esc(p.restrictions)}</textarea></label></div><div class="hint">Targets are optional references you set. The app does not infer calorie needs from blank profile fields.</div><button class="btn">${icon('check')} Save settings</button></form></section><div class="stack"><section class="card"><h2>Weekly training schedule</h2><p class="small muted">Add sessions, change days and times, or remove workouts from your recurring week.</p><button class="btn" data-action="training-schedule">Edit weekly schedule</button></section><section class="card"><h2>Your data, your device</h2><p class="small muted">Your diary and plans are stored in this browser. They do not automatically sync between devices or between this private version and GitHub Pages.</p><div class="actions" style="margin-top:18px"><button class="btn" data-action="export">${icon('download')} Export backup</button><button class="btn secondary" data-action="restore">Restore backup</button></div><input type="file" id="backup-file" accept="application/json,.json" hidden><p class="small muted">Back up regularly. Clearing browser data removes local entries.</p></section><section class="card"><h2>Install Fuel & Flow</h2><p class="small muted">An offline-capable PWA, like HoopTrack. In Chrome on Android, use the browser menu → Install app / Add to Home screen. Open once online before using offline.</p>${installEvent?'<button class="btn" data-action="install">Install app</button>':''}<div class="hint">On an owner-private host, initial sign-in may need a connection. GitHub Pages has a standalone offline shell.</div></section><section class="card"><h2>Track what matters to you</h2><p class="small muted">Track food, training, energy and recovery together. Use your logs to coordinate practical changes with ChatGPT.</p><p class="small muted">Persistent unexplained fatigue deserves a clinical assessment. This app tracks observations and does not diagnose fatigue.</p></section></div></div>`;}
function applyTheme(){const theme=state.profile.theme;document.body.classList.toggle('dark',theme==='dark'||theme==='system'&&matchMedia('(prefers-color-scheme: dark)').matches);}
function render(){applyTheme();const labels={today:['Your daily rhythm','Today'],plan:['Meals with a purpose','Meal plan'],insights:['See the bigger picture','Trends'],coach:['Coordinate your next step','ChatGPT'],settings:['Make it yours','Settings']};$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><img class="brandmark" src="./icons/logo.svg" alt="Fuel & Flow logo"><div>Fuel & Flow<small>ENERGY IN. LIFE OUT.</small></div></div><nav class="nav" aria-label="Main navigation">${[['today','Today','sun'],['plan','Meal plan','food'],['insights','Trends','chart'],['coach','ChatGPT','chat'],['settings','Settings','settings']].map(([id,n,i])=>`<button data-action="nav" data-view="${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${icon(i)}${n}</button>`).join('')}</nav><div class="sidebar-footer"><span class="avatar">${esc((state.profile.name||'F')[0])}</span> ${esc(state.profile.name||'you')}’s daily flow<br>Local-first · private by design<br><span style="font-size:10px">v1.4.3 · back up in Settings</span></div></aside><main><header><div><div class="eyebrow">${labels[view][0]}</div><h1>${view==='today'?`Let’s find your flow, ${esc(state.profile.name||'you')}.`:labels[view][1]}</h1></div><div class="actions">${['today','insights'].includes(view)?`<button class="iconbtn" data-action="prev-day" aria-label="Previous day">←</button><label class="small" aria-label="Selected date"><input type="date" id="selected-date" value="${selected}" required></label><button class="iconbtn" data-action="next-day" aria-label="Next day">→</button>`:''}<span class="pill">${view==='today'?esc(d().type):'Food · energy · recovery'}</span></div></header>${({today:todayHTML,plan:planHTML,insights:insightsHTML,coach:coachHTML,settings:settingsHTML}[view])()}<div class="footer-note">Small adjustments. Useful patterns. A stronger tomorrow.</div></main></div>`;bindForms();}
function openModal(html){const modal=$('#modal');modal.innerHTML=html;modal.showModal();modal.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>modal.close());}
function confirmDialog(title,text,action){openModal(`<h2>${esc(title)}</h2><p>${esc(text)}</p><div class="modal-actions"><button class="btn secondary" data-close>Cancel</button><button class="btn" id="confirm-action">Confirm</button></div>`);$('#confirm-action').onclick=()=>{$('#modal').close();action();};}

function fuelLabel(minutes){const session=sessionsFor(selected,state.weeklyTraining).find(x=>x.type==='BJJ');if(!session?.time)return 'Flexible';const [h,m]=session.time.split(':').map(Number),t=((h*60+m+minutes)%1440+1440)%1440;return time(`${String(Math.floor(t/60)).padStart(2,'0')}:${String(t%60).padStart(2,'0')}`);}
function bjjLabel(date){const session=sessionsFor(date,state.weeklyTraining).find(x=>x.type==='BJJ');return session?.time?time(session.time):'scheduled';}
function trainingDialog(){const names=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];openModal(`<h2>Weekly training schedule</h2><p class="small muted">Your recurring week. Changes apply to planned days and ChatGPT prompts; historical logs keep their recorded training type.</p>${[1,2,3,4,5,6,0].map(day=>{const sessions=state.weeklyTraining.filter(x=>x.day===day);return `<section class="training-day"><div class="card-head"><h3>${names[day]}</h3><button class="btn secondary" data-add-training="${day}">${icon('plus')} Add session</button></div>${sessions.length?sessions.map(x=>swipeRecord(`<h3>${esc(x.title)}</h3><p>${esc(x.type)} · ${x.time?esc(time(x.time)):'Time flexible'}${x.duration!==null?' · '+x.duration+' min':''}${x.intensity?' · '+esc(x.intensity):''}</p>`,[{kind:'copy',icon:'copy',label:'Copy',attrs:`data-copy-training="${esc(x.id)}"`},{kind:'edit',icon:'edit',label:'Edit',attrs:`data-edit-training="${esc(x.id)}"`},{kind:'delete',icon:'trash',label:'Delete',attrs:`data-delete-training="${esc(x.id)}"`}],x.title)).join(''):'<p class="small muted">No sessions · rest day</p>'}</section>`;}).join('')}<div class="modal-actions"><button class="btn secondary" data-close>Close</button></div>`);$('#modal').querySelectorAll('[data-add-training]').forEach(b=>b.onclick=()=>{$('#modal').close();trainingForm({day:Number(b.dataset.addTraining),type:'Weights',title:'',time:'',duration:null,intensity:'Moderate'});});$('#modal').querySelectorAll('[data-copy-training]').forEach(b=>b.onclick=()=>{$('#modal').close();trainingForm(state.weeklyTraining.find(x=>x.id===b.dataset.copyTraining),true);});$('#modal').querySelectorAll('[data-edit-training]').forEach(b=>b.onclick=()=>{$('#modal').close();trainingForm(state.weeklyTraining.find(x=>x.id===b.dataset.editTraining));});$('#modal').querySelectorAll('[data-delete-training]').forEach(b=>b.onclick=()=>{const id=b.dataset.deleteTraining;$('#modal').close();confirmDialog('Delete this recurring session?','This removes it from your weekly schedule, leaving historical food and training logs intact.',()=>{state.weeklyTraining=state.weeklyTraining.filter(x=>x.id!==id);persist();render();trainingDialog();});});}
function trainingForm(session,copyOpen=false){const names=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];openModal(`<h2>${session.id?'Edit':'Add'} training session</h2><form id="training-form"><div class="fields"><label class="field">Day<select name="day">${names.map((n,i)=>`<option value="${i}" ${i===session.day?'selected':''}>${n}</option>`).join('')}</select></label><label class="field">Training type<select name="type">${['BJJ','Weights','Walk','Rest','Other'].map(t=>`<option ${t===session.type?'selected':''}>${t}</option>`).join('')}</select></label><label class="field wide">Session name<input name="title" maxlength="150" value="${esc(session.title)}" required placeholder="e.g. Upper body or Jiu-jitsu"></label><label class="field">Start time (optional)<input name="time" type="time" value="${session.time}"></label><label class="field">Duration in minutes (optional)<input name="duration" type="number" min="0" max="600" step="1" value="${session.duration??''}"></label><label class="field wide">Intensity<select name="intensity">${['Light','Moderate','Hard'].map(i=>`<option value="${i}" ${i===normalizeIntensity(session.intensity)?'selected':''}>${i}</option>`).join('')}</select></label></div><details style="margin-top:20px" ${copyOpen?'open':''}><summary><strong>Copy workout to other days</strong></summary><div class="hint">Copies add this workout to your recurring schedule with the same time, duration and intensity. Existing workouts and historical logs stay intact.</div><label class="check" style="margin:14px 0"><input type="checkbox" name="copyWorkoutAll" id="copy-workout-all"> Entire Monday–Sunday week</label><div class="copy-grid" id="copy-workout-days">${[1,2,3,4,5,6,0].map(day=>`<label class="check"><input type="checkbox" name="copyWorkoutDays" value="${day}"> ${names[day]}</label>`).join('')}</div><p class="small muted">The workout’s selected day is saved once and excluded from additional copies.</p></details><div class="modal-actions"><button type="button" class="btn secondary" data-close>Cancel</button><button class="btn">Save workout & selected copies</button></div></form>`);$('#copy-workout-all').onchange=e=>$('#copy-workout-days').querySelectorAll('input').forEach(x=>x.disabled=e.target.checked);$('#training-form').onsubmit=e=>{e.preventDefault();try{const form=new FormData(e.target),raw=Object.fromEntries(form);const days=raw.copyWorkoutAll==='on'?[0,1,2,3,4,5,6]:form.getAll('copyWorkoutDays').map(Number);const count=saveWorkout(state,{...raw,day:Number(raw.day),duration:raw.duration===''?null:Number(raw.duration)},days,session.id||null);persist();$('#modal').close();render();trainingDialog();toast(`Workout saved${count?` with ${count} copies`:''}.`);}catch(err){toast(err.message);}};}

function usualDialog(){openModal(`<div class="card-head"><h2>Your usual foods</h2><button class="btn" id="new-usual">${icon('plus')} Add food</button></div><p class="small muted">Edit your own portions and macros. Changes here don’t alter meals you already logged.</p>${state.usualFoods.length?state.usualFoods.map((m,i)=>swipeRecord(`<h3>${esc(m.name)}</h3><p>${esc(m.portion)}</p><p>${fmt(m.calories)} kcal · P ${fmt(m.protein)} · C ${fmt(m.carbs)} · F ${fmt(m.fat)}</p><button class="btn soft" data-use-usual="${i}">Log this food</button>`,[{kind:'edit',icon:'edit',label:'Edit',attrs:`data-edit-usual="${i}"`},{kind:'delete',icon:'trash',label:'Delete',attrs:`data-delete-usual="${i}"`}],m.name)).join(''):'<div class="empty">No usual foods yet. Add your first food above.</div>'}<div class="modal-actions"><button class="btn secondary" data-close>Close</button></div>`);$('#new-usual').onclick=()=>{$('#modal').close();mealDialog(null,false,null,true);};$('#modal').querySelectorAll('[data-use-usual]').forEach(b=>b.onclick=()=>{$('#modal').close();mealDialog({...state.usualFoods[Number(b.dataset.useUsual)],id:undefined});});$('#modal').querySelectorAll('[data-edit-usual]').forEach(b=>b.onclick=()=>{$('#modal').close();mealDialog(state.usualFoods[Number(b.dataset.editUsual)],false,null,true);});$('#modal').querySelectorAll('[data-delete-usual]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.deleteUsual);$('#modal').close();confirmDialog('Remove usual food?',state.usualFoods[i].name,()=>{state.usualFoods.splice(i,1);persist();usualDialog();});});}
function mealDialog(meal=null,planned=false,index=null,usual=false){const source=planned?planDay:selected,m=meal||{name:'',time:'12:00',portion:'',calories:'',protein:'',carbs:'',fat:''};openModal(`<h2>${usual?(meal?'Edit usual food':'Add usual food'):meal?'Edit a meal':'Add meal'}</h2><p class="small muted">Enter the nutrition for one serving. ${usual?'Save it for quick reuse.':'Save here and optionally copy that serving to other days.'}</p><form id="meal-form">${!usual?`<label class="field" style="margin-bottom:18px">Fill from Usual foods<select id="meal-usual"><option value="">Choose a saved food…</option>${state.usualFoods.map((f,i)=>`<option value="${i}">${esc(f.name)}</option>`).join('')}</select></label>`:''}<div class="fields"><label class="field wide">Meal / food name<input name="name" required maxlength="150" value="${esc(m.name)}"></label>${!usual?`<label class="field">Meal date<input name="date" type="date" required value="${source}"></label>`:''}<label class="field">${usual?'Usual time':'Meal time'}<input name="time" type="time" required value="${m.time}"></label><label class="field wide">Portion / ingredients<input name="portion" required maxlength="1000" value="${esc(m.portion)}" placeholder="Include amount and units"></label>${['calories','protein','carbs','fat'].map(k=>`<label class="field">${k==='calories'?'Calories (kcal)':k[0].toUpperCase()+k.slice(1)+' (g)'}<input name="${k}" type="number" min="0" max="10000" step="0.1" required value="${m[k]}"></label>`).join('')}</div>${!usual?`<hr class="divider"><label class="check"><input type="checkbox" name="saveUsual"> Also save as a usual food</label><details style="margin-top:18px"><summary>${icon('copy')} Copy this meal to other days</summary><div class="hint">Copies add servings; they do not replace meals. Future meals normally belong in your meal plan. Eaten-food copies are recorded only when you choose that destination.</div><div class="fields"><label class="field">Week containing dates<input name="copyWeek" id="copy-week" type="date" value="${weekStart(source)}"></label><label class="field">Copy destination<select name="copyDestination"><option value="plan">Meal plan (not eaten)</option><option value="actual">Eaten-food log</option></select></label></div><label class="check" style="margin:15px 0"><input type="checkbox" name="copyAll" id="copy-all"> Entire Monday–Sunday week</label><div id="copy-days" class="copy-grid"></div><p class="small muted">The saved meal’s date is excluded from copies. For another week, choose a date within that week above.</p></details>`:''}<div class="modal-actions"><button class="btn secondary" type="button" data-close>Cancel</button><button class="btn">${usual?'Save usual food':'Save meal & selected copies'}</button></div></form>`);
 if(!usual){$('#meal-usual').onchange=e=>{if(e.target.value==='')return;const food=state.usualFoods[Number(e.target.value)];for(const key of ['name','portion','time','calories','protein','carbs','fat'])$('#meal-form').elements.namedItem(key).value=food[key];};const updateDays=()=>{const start=$('#copy-week').value;if(!start)return;$('#copy-days').innerHTML=range(start,'week').map(k=>`<label class="check"><input type="checkbox" name="copyDates" value="${k}"> ${dateObj(k).toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'})}</label>`).join('');};updateDays();$('#copy-week').onchange=updateDays;$('#copy-all').onchange=e=>$('#copy-days').querySelectorAll('input').forEach(x=>{x.disabled=e.target.checked;});}
 $('#meal-form').onsubmit=e=>{e.preventDefault();try{const form=new FormData(e.target),raw=Object.fromEntries(form);for(const k of ['calories','protein','carbs','fat'])raw[k]=Number(raw[k]);const clean=validateMeal(raw);let count=0;const newState=structuredClone(state);if(usual){if(meal?.id)newState.usualFoods=newState.usualFoods.map(x=>x.id===meal.id?{...clean,id:x.id}:x);else newState.usualFoods.push({...clean,id:crypto.randomUUID()});}else{const date=raw.date;if(!validDate(date))throw Error('Choose a valid meal date.');const copyTo=copyDates(raw.copyWeek,form.getAll('copyDates'),raw.copyAll==='on',date);if(planned){if(index!==null)newState.plans[source].meals.splice(index,1);applyMeals(newState,[{...clean,date}],'plan');}else{if(meal?.id){newState.days[source].meals=newState.days[source].meals.filter(x=>x.id!==meal.id);newState.days[source].complete=false;}applyMeals(newState,[{...clean,date}],'actual');}if(raw.saveUsual==='on')applyMeals(newState,[clean],'usual');count=applyMeals(newState,copyTo.map(date=>({...clean,date})),raw.copyDestination);if(!planned)selected=date;else planDay=date;}state=newState;persist();$('#modal').close();render();toast(usual?'Usual food saved.':`Meal saved${count?` with ${count} copies`:''}.`);}catch(err){toast(err.message);}};
}
function importDialog(){let currentPrompt='',stampSource='Manually confirmed date/time',reading=0;openModal(`<h2>Import meals & macros</h2><p class="small muted">Describe a meal or attach a photo in ChatGPT. Paste its structured response here to review and save.</p><details open><summary><strong>1. Create a photo / meal prompt</strong></summary><div class="hint">Select the same original photo here to read its capture time when available, then attach that photo separately in ChatGPT. This app does not upload your photo.</div><label class="field">Optional original photo<input type="file" id="meal-photo" accept="image/*"></label><p id="photo-status" class="small muted">Photos without capture metadata need a manually confirmed date and time.</p><div class="fields"><label class="field">Capture / meal date<input type="date" id="photo-date"></label><label class="field">Capture / meal time<input type="time" id="photo-time"></label><label class="field wide">Portion & ingredient notes<textarea id="photo-context" placeholder="e.g. 2 tacos, 93% lean beef, corn tortillas; amounts if known"></textarea></label></div><button class="btn secondary" type="button" id="make-photo-prompt" style="margin:15px 0">Generate photo / meal prompt</button><label class="field">Copy this with your photo into ChatGPT<textarea id="photo-prompt-output" class="prompt-box" readonly></textarea></label><div class="actions" style="margin:12px 0"><button class="btn soft" id="copy-photo-prompt" type="button">Copy prompt</button><a class="btn secondary" href="https://chatgpt.com/" target="_blank" rel="noopener">Open ChatGPT ↗</a></div></details><hr class="divider"><h3>2. Paste ChatGPT’s JSON response</h3><label class="field">Meal data<textarea id="meal-json" class="prompt-box" placeholder='{"schemaVersion":1,"meals":[{"date":"2026-10-12","time":"12:00","name":"…","portion":"…","calories":500,"protein":30,"carbs":50,"fat":20}]}'></textarea></label><label class="field small" style="margin-top:10px">Or choose a JSON file<input type="file" id="meal-json-file" accept=".json,application/json"></label><button class="btn" id="preview-meals" type="button" style="margin-top:15px">Validate & review meals</button><div id="meal-import-review"></div><div class="modal-actions"><button class="btn secondary" data-close>Close</button></div>`);
 $('#meal-photo').onchange=async e=>{const file=e.target.files?.[0],token=++reading;if(!file)return;$('#photo-date').value='';$('#photo-time').value='';stampSource='Capture metadata unavailable; use manually confirmed values if entered';try{if(file.size>30e6)throw Error('Use a photo under 30MB.');const stamp=captureTime(await file.arrayBuffer());if(token!==reading)return;if(stamp){$('#photo-date').value=stamp.date;$('#photo-time').value=stamp.time;stampSource=stamp.source;$('#photo-status').textContent=`Capture time found: ${stamp.date} ${stamp.time}. Confirm it matches your local meal time.`;}else $('#photo-status').textContent='No readable original capture time found. Enter the date/time from your photo’s Details screen, or leave them blank and fill them during import.';}catch(err){$('#photo-status').textContent=err.message;}};
 for(const sel of ['#photo-date','#photo-time'])$(sel).oninput=()=>{stampSource='Date/time manually confirmed by user';};
 $('#make-photo-prompt').onclick=()=>{currentPrompt=photoPrompt({date:$('#photo-date').value,time:$('#photo-time').value,source:stampSource,context:$('#photo-context').value});$('#photo-prompt-output').value=currentPrompt;};
 $('#copy-photo-prompt').onclick=()=>{if(!currentPrompt){toast('Generate your prompt first.');return;}copy(currentPrompt);};
 const invalidate=()=>{$('#meal-import-review').innerHTML='';};$('#meal-json').oninput=invalidate;
 $('#meal-json-file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>1e6)throw Error('Use a JSON file under 1MB.');$('#meal-json').value=await file.text();invalidate();}catch(err){toast(err.message);}};
 $('#preview-meals').onclick=()=>{try{const entries=parseMeals($('#meal-json').value);$('#meal-import-review').innerHTML=`<div class="banner success">${entries.length} meal(s) ready for review. Edit any estimates below.</div><form id="meal-import-form"><label class="field">Save to<select name="destination"><option value="actual">Eaten-food log</option><option value="plan">Meal plan (not eaten)</option><option value="usual">Usual foods only</option></select></label>${entries.map((m,i)=>`<fieldset class="import-entry"><legend>Meal ${i+1}</legend><div class="fields"><label class="field wide">Name<input name="name-${i}" value="${esc(m.name)}" required maxlength="150"></label><label class="field">Date<input type="date" name="date-${i}" value="${m.date||$('#photo-date').value}" required></label><label class="field">Time<input type="time" name="time-${i}" value="${m.time||$('#photo-time').value}" required></label><label class="field wide">Portions & assumptions<input name="portion-${i}" value="${esc(m.portion)}" required maxlength="1000"></label>${['calories','protein','carbs','fat'].map(k=>`<label class="field">${k==='calories'?'Calories (kcal)':k+' (g)'}<input type="number" name="${k}-${i}" min="0" max="10000" step="0.1" value="${m[k]}" required></label>`).join('')}</div></fieldset>`).join('')}<label class="check" style="margin:15px 0"><input type="checkbox" name="alsoUsual"> Also save imported meals as usual foods</label><p class="small muted">Saves add servings, including repeats. Imported food logs remain partial until you mark the day complete. Photo nutrition is approximate.</p><button class="btn">Save reviewed meals</button></form>`;
 $('#meal-import-form').querySelector('select').onchange=e=>{$('#meal-import-form').querySelectorAll('input[type=date]').forEach(x=>x.required=e.target.value!=='usual');};
 $('#meal-import-form').onsubmit=e=>{e.preventDefault();try{const f=Object.fromEntries(new FormData(e.target));const cleaned=entries.map((_,i)=>({date:f[`date-${i}`],time:f[`time-${i}`],name:f[`name-${i}`],portion:f[`portion-${i}`],...Object.fromEntries(['calories','protein','carbs','fat'].map(k=>[k,Number(f[`${k}-${i}`])]))}));const newState=structuredClone(state);const count=applyMeals(newState,cleaned,f.destination);if(f.alsoUsual==='on'&&f.destination!=='usual')applyMeals(newState,cleaned,'usual');state=newState;persist();$('#modal').close();if(f.destination==='actual')selected=cleaned[0].date;render();toast(`${count} meal(s) imported.`);}catch(err){toast(err.message);}};
 }catch(err){$('#meal-import-review').innerHTML=`<div class="banner" role="alert">${esc(err.message)}</div>`;}};
}

function bindForms(){if($('#checkin'))$('#checkin').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target)),day=ensure();for(const k of ['energyBefore','energyAfter','sleep','water','weight','waist','bjjMinutes','liftMinutes'])day[k]=f[k]===''?null:Number(f[k]);day.notes=f.notes;day.recovery=f.recovery;persist();render();toast('Check-in saved.');};if($('#settings'))$('#settings').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));if(f.energyGoal!==''&&(Number(f.energyGoal)<1||Number(f.energyGoal)>10)){toast('Energy goal must be 1–10.');return;}for(const k of ['age','weight','startWeight','goalWeight','energyBaseline','energyGoal','hydrationGoal','protein','bjjCarbs','otherCarbs','fat'])if(f[k]!=='')f[k]=Number(f[k]);if(f.energyBaseline!==''&&(Number(f.energyBaseline)<1||Number(f.energyBaseline)>10)){toast('Starting energy must be 1–10.');return;}if(f.hydrationGoal!==''&&(!Number.isFinite(Number(f.hydrationGoal))||Number(f.hydrationGoal)<=0||Number(f.hydrationGoal)>500)){toast('Hydration goal must be between 1 and 500 oz, or left blank.');return;}state.profile={...state.profile,...f};persist();render();toast('Settings saved.');};if($('#complete'))$('#complete').onchange=e=>{ensure().complete=e.target.checked;persist();render();};if($('#training-type'))$('#training-type').onchange=e=>{ensure().type=e.target.value;persist();render();};if($('#selected-date'))$('#selected-date').onchange=e=>{if(e.target.value){selected=e.target.value;render();}};if($('#backup-file'))$('#backup-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5e6)throw Error('Backup is too large (maximum 5MB).');const restored=validateBackup(JSON.parse(await file.text()));confirmDialog('Restore this backup?',`${Object.keys(restored.days).length} diary days and ${Object.keys(restored.plans).length} planned days. This replaces your current local data. Export a backup first if needed.`,()=>{state=restored;persist();render();toast('Backup restored.');});}catch(err){toast(err.message);}};}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copied. Paste into ChatGPT.');}catch{if($('#modal').open&&$('#photo-prompt-output')){$('#photo-prompt-output').focus();$('#photo-prompt-output').select();toast('Select and copy the prompt manually.');return;}openModal(`<h2>Copy your prompt</h2><p>Select all and copy the text below.</p><textarea id="copy-fallback" class="prompt-box" style="width:100%" readonly>${esc(text)}</textarea><div class="modal-actions"><button class="btn" data-close>Done</button></div>`);$('#copy-fallback').focus();$('#copy-fallback').select();}}
function exportBackup(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`fuel-and-flow-backup-${dateKey()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Backup downloaded.');}
function normalizedWeek(value){if(!value)throw Error('Choose a starting date.');const s=weekStart(value);if(s!==value)throw Error('Choose a Monday as the week starting date.');return s;}
$('#app').addEventListener('input',e=>{if(['plan-input','import-week'].includes(e.target.id)&&draft){draft=null;$('#import-preview').innerHTML='<div class="hint">Response changed. Validate and review it again before importing.</div>';}});
function previewImport(){try{planStart=normalizedWeek($('#import-week').value);draft=parsePlan($('#plan-input').value,planStart);const days=Object.keys(draft).sort();$('#import-preview').innerHTML=`<div class="banner success">Seven days validated. Review estimated daily totals below.</div><div class="table-scroll"><table><thead><tr><th>Day</th><th>Meals</th><th>kcal</th><th>P / C / F</th></tr></thead><tbody>${days.map(k=>{const t=totals(draft[k].meals);return `<tr><td>${pretty(k)}</td><td>${draft[k].meals.length}</td><td>${fmt(t.calories)}</td><td>${fmt(t.protein)} / ${fmt(t.carbs)} / ${fmt(t.fat)}</td></tr>`;}).join('')}</tbody></table></div><details style="margin:15px 0"><summary>Review all meal names and portions</summary>${days.map(k=>`<h3 style="margin-top:15px">${pretty(k)}</h3>${mealsHTML(draft[k].meals,false,selected,false).replace(/<div class="meal-buttons">[\s\S]*?<\/div>/g,'')}`).join('')}</details><button class="btn" data-action="commit-import">Import reviewed week</button>`;}catch(err){draft=null;$('#import-preview').innerHTML=`<div class="banner" role="alert">${esc(err.message)}</div>`;}}
$('#app').addEventListener('change',e=>{if(e.target.dataset.groceryIndex!==undefined){const item=groceryList(state,planStart).items[Number(e.target.dataset.groceryIndex)];if(!item)return;const checked=new Set(state.groceryChecks[planStart]||[]);if(e.target.checked)checked.add(item.key);else checked.delete(item.key);state.groceryChecks[planStart]=[...checked];persist();render();}});
attachMealSwipes($('#app'));
attachMealSwipes($('#modal'));
$('#app').addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;
if(action==='nav'){view=b.dataset.view;draft=null;render();window.scrollTo(0,0);}
if(action==='prev-day'||action==='next-day'){selected=addDays(selected,action==='prev-day'?-1:1);render();}
if(action==='open-day'){selected=b.dataset.date;view='today';render();}
if(action==='add-meal')mealDialog();
if(action==='edit-meal')mealDialog(d().meals.find(x=>x.id===b.dataset.id));
if(action==='delete-meal')confirmDialog('Remove this food entry?','This removes the serving from this day’s actual food log.',()=>{ensure().meals=d().meals.filter(x=>x.id!==b.dataset.id);persist();render();});
if(action==='training-schedule')trainingDialog();
if(action==='favorites')usualDialog();
if(action==='meal-import')importDialog();
if(action==='show-today-plan'){planDay=selected;planStart=weekStart(selected);view='plan';render();}
if(action==='plan-prev'||action==='plan-next'){planStart=addDays(planStart,action==='plan-prev'?-7:7);planDay=planStart;render();}
if(action==='next-week'){planStart=nextWeek();planDay=planStart;render();}
if(action==='copy-groceries'){const text=groceryText(groceryList(state,planStart),planStart,addDays(planStart,6));try{await navigator.clipboard.writeText(text);toast('Grocery list copied.');}catch{openModal(`<h2>Copy grocery list</h2><textarea id="grocery-copy" class="prompt-box" style="width:100%" readonly>${esc(text)}</textarea><div class="modal-actions"><button class="btn secondary" data-close>Close</button></div>`);$('#grocery-copy').focus();$('#grocery-copy').select();}}
if(action==='plan-day'){planDay=b.dataset.date;render();}
if(action==='add-plan')mealDialog(null,true);
if(action==='edit-plan-day'){const meals=state.plans[planDay].meals;openModal(`<div class="card-head"><h2>Edit planned meals</h2><button class="btn soft" id="add-planned-usual">Add from Usual foods</button></div>${meals.map((m,i)=>`<div class="meal"><div class="meal-body"><h3>${esc(m.name)}</h3><p>${esc(m.portion)}</p></div><button class="iconbtn" data-plan-edit="${i}" aria-label="Edit ${esc(m.name)}">${icon('edit')}</button><button class="iconbtn" data-plan-delete="${i}" aria-label="Remove ${esc(m.name)}">${icon('trash')}</button></div>`).join('')}<div class="modal-actions"><button class="btn secondary" data-close>Close</button></div>`);$('#add-planned-usual').onclick=()=>{$('#modal').close();mealDialog(null,true);};$('#modal').querySelectorAll('[data-plan-edit]').forEach(x=>x.onclick=()=>{$('#modal').close();mealDialog(meals[Number(x.dataset.planEdit)],true,Number(x.dataset.planEdit));});$('#modal').querySelectorAll('[data-plan-delete]').forEach(x=>x.onclick=()=>{$('#modal').close();confirmDialog('Remove planned meal?','Only the plan will change.',()=>{meals.splice(Number(x.dataset.planDelete),1);persist();render();});});}
if(action==='delete-planned-meal'){const date=b.dataset.date,index=Number(b.dataset.index),meal=state.plans[date]?.meals[index];if(meal)confirmDialog('Delete this planned meal?',meal.name+' will be removed from the plan. Logged food stays intact.',()=>{if(state.plans[date]?.meals[index]!==meal){toast('The plan changed. Reopen the meal before deleting.');return;}state.plans[date].meals.splice(index,1);persist();render();toast('Planned meal deleted.');});}
if(action==='edit-planned-meal'){const date=b.dataset.date,index=Number(b.dataset.index);if(state.plans[date]?.meals[index]){planDay=date;mealDialog(state.plans[date].meals[index],true,index);}}
if(action==='eat-plan'){const date=b.dataset.date,m=state.plans[date].meals[Number(b.dataset.index)];const eat=()=>{const day=state.days[date]??=freshDay(date,state.weeklyTraining);day.meals.push({...m,id:crypto.randomUUID()});day.meals.sort((a,b)=>a.time.localeCompare(b.time));persist();toast(`Logged eaten for ${pretty(date)}.`);};confirmDialog('Log this meal as eaten?',`${m.name} · ${m.portion}. This adds one serving to ${pretty(date)}, even if already logged.`,eat);}
if(action==='period'){period=b.dataset.period;render();}
if(action==='review-coach'){coachMode='review';coachPrompt=reviewPrompt(state,selected,period);view='coach';render();}
if(action==='plan-coach'){coachMode='plan';coachPrompt=planPrompt(state,planStart);view='coach';render();}
if(action==='copy-review')copy(reviewPrompt(state,selected,period));
if(action==='coach-mode'){coachMode=b.dataset.mode;coachPrompt='';render();}
if(action==='generate'){try{if(coachMode==='review'){period=$('#review-period').value;selected=$('#review-date').value;if(!selected)throw Error('Choose a review date.');coachPrompt=reviewPrompt(state,selected,period);}else{planStart=normalizedWeek($('#coach-week').value);coachPrompt=planPrompt(state,planStart);}render();toast('Prompt ready to copy.');}catch(err){toast(err.message);}}
if(action==='copy-prompt')copy(coachPrompt);
if(action==='preview-import')previewImport();
if(action==='commit-import'&&draft){const imported=draft;const dates=Object.keys(imported).sort();confirmDialog('Import this reviewed week?',`Replace planned meals for ${pretty(dates[0])} through ${pretty(dates.at(-1))}? Your eaten food and check-ins stay separate.`,()=>{for(const k of dates)state.plans[k]=imported[k];persist();draft=null;planDay=dates[0];planStart=dates[0];view='plan';render();toast('Meal plan imported.');});}
if(action==='export')exportBackup();
if(action==='restore')$('#backup-file').click();
if(action==='install'&&installEvent){await installEvent.prompt();installEvent=null;render();}
});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installEvent=e;if(view==='settings')render();});
window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){try{state=validateBackup(JSON.parse(e.newValue));render();toast('Updated from another tab.');}catch{toast('Could not read an update from another tab.');}}});
matchMedia('(prefers-color-scheme: dark)').addEventListener('change',applyTheme);
render();if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).catch(()=>{});
